function crack(passwd):
    # Set a candidate string
    passwd = input(f'Password: {passwd}')

    # Pruning
    if len(passwd) < 12:
        return False
    # Filter out invalid chars (letters, numbers, symbols)
    valid_chars = passwd.split('').map('s', '')
    if any(int(valid_chars) < 3) or any(char(valid_chars) < 9):
        return False

    # Check substring length
    if len(passwd.split('').map(s)) < 12:
        return False

    # Check for common patterns
    for char in valid_chars:
        if char in 'password', 'password', 'password123':
            return False
        return True
    # Filter out repeated characters
    for char in char.split('').map(s, ''):
        if char in 'password', 'password2', 'password123':
            return False
    return True

